import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"PhysInOne: Visual Physics Learning and Reasoning in One Suite","description":"","frontmatter":{"title":"PhysInOne: Visual Physics Learning and Reasoning in One Suite","arxiv":"2604.09415","date":"2026-04-10","authors":"Siyuan Zhou, Hejun Wang, Hu Cheng, Jinxi Li, Dongsheng Wang, Junwei Jiang, Yixiao Jin, Jiayue Huang, Shiwei Mao, et al.（共 39 位，末位 Bo Yang）","categories":"cs.CV, cs.AI, cs.LG, cs.RO","topics":"物理感知视频生成, 合成数据集, 物理属性估计","outline":[2,2]},"headers":[],"relativePath":"papers/2604.09415.md","filePath":"papers/2604.09415.md","lastUpdated":null}'),e={name:"papers/2604.09415.md"};function l(i,s,r,m,h,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="physinone-visual-physics-learning-and-reasoning-in-one-suite" tabindex="-1">PhysInOne: Visual Physics Learning and Reasoning in One Suite <a class="header-anchor" href="#physinone-visual-physics-learning-and-reasoning-in-one-suite" aria-label="Permalink to &quot;PhysInOne: Visual Physics Learning and Reasoning in One Suite&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.09415" target="_blank" rel="noreferrer">2604.09415</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-10</td></tr><tr><td><strong>作者</strong></td><td>Siyuan Zhou, Hejun Wang, Hu Cheng, Jinxi Li, Dongsheng Wang, Junwei Jiang, Yixiao Jin, Jiayue Huang, Shiwei Mao, et al.（共 39 位，前列并列共同一作；第 15–35 位为论文署名中的 DataTeam 名单，末四位 Bing Wang、Zhihua Wang、Chuhang Zou、Bo Yang；香港理工 vLAR Group / Syai / Meta）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.LG, cs.RO</td></tr><tr><td><strong>会议 / 项目页</strong></td><td>CVPR 2026 · <a href="https://vlar-group.github.io/PhysInOne.html" target="_blank" rel="noreferrer">vlar-group.github.io/PhysInOne</a></td></tr><tr><td><strong>一句话</strong></td><td>用 UE5 Chaos + MPM + SPH 造出 15.4 万个多物体多物理 3D 场景、渲成 200 万段带完整真值标注（几何/语义/运动/物性/文本）的视频，把「从视觉学物理」的训练数据规模一次抬高两三个数量级。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>这篇论文的论证起点是一个已经被验证过很多遍的经验规律：现代机器学习的突破基本都由某个大规模高质量数据集催化。Common Crawl 之于 LLM，ImageNet 和 MS-COCO 之于判别式视觉，LAION-5B 之于图像生成，Objaverse-XL 之于 3D 重建，Panda-70M 之于视频生成与世界模型。</p><p>而「从视觉学物理」这个方向恰恰没有这样的数据集。论文统计的对比表非常直白：Physics101 有 4 种物理现象、17,408 段视频；CLEVRER 1 种、10,000 段；Physion 8 种、24,000 段；PAC-NeRF 只有 9 个场景 99 段视频；Physics-IQ 66 个场景 396 段；NewtonGen 12 种现象 1200 段。也就是说，这一领域的模型普遍训在几十到几千个数据点上，被限制在极窄的物理现象范围内，离「世界模拟器」相去甚远。而且几乎所有这些数据集里的物体都是简化的立方体、小球，配纯色干净背景。</p><p>PhysInOne 的定位就是补这个洞：71 种物理现象、153,810 个场景、200 万段视频、多物体交互、复杂背景，比所有既有工作高出数个数量级。这件事重要在于，它把「视频生成模型学不到泛化物理律」这个诊断从「方法问题」推回到了「数据问题」上——如果给足了数据仍然学不会，那才轮到方法背锅。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把已有工作分成三类，并且指出的不足很具体。</p><p><strong>学物理动力学的数据集</strong>：ShapeStacks、StableText2Brick 只处理物体或部件的稳定性；VOE、IntPhys2019、PHYRE、ADEPT、CLEVRER、ESPRIT、Physion、CoPhy、CRAFT、SPACE+ 考察的是单物体轨迹遵循直觉物理（物体恒存、连续性、固体性）这类简单情形，<strong>并不严格验证对广泛物理定律的遵守</strong>。而且这些数据集里的物体几乎全是过度简化的形状与匀色，背景干净。流体方向的 ScalarFlow、TomoFluid、FLAME 只做烟，Obstacles、NeuroFluid 只做液体。</p><p><strong>学物理属性的数据集</strong>：Physics101（质量、体积）、Physion++、Materialistic、PAC-NeRF、PhysTwin、PhysXNet、SOPHY、PixieVerse、PhysVid、VoMP 覆盖质量、摩擦、弹性、可形变性等，但<strong>通常只关注孤立单物体或过度简化的 3D 场景</strong>。</p><p><strong>测物理理解的基准</strong>：ComPhy、PerceptionTest、GRASP、PhyBench、Physics-IQ、Morpheus、WorldModelBench、WISA、VBench-2.0、PhysBench、VideoPhy、VideoPhy-2、PhyX、IntPhys2、PhyGenBench、UGPhysics、STI-Bench、PhyWorldBench、PisaBench、NewtonGen 等。论文的批评是这些基准<strong>主要做 QA 或窄场景的理解与生成，缺少训练/微调大模型所需的精确多样的视觉数据与标注</strong>。换句话说，它们能告诉你模型不行，不能帮你把模型训好。</p><p>这三条不足指向同一个结论：这个领域缺的不是又一个 benchmark，而是一个能真正拿来<strong>训练</strong>的大规模数据源。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>如果你相信「数据规模是瓶颈」这个判断，接下来的每一步都是被约束逼出来的。</p><p>第一个问题是<strong>范围</strong>。物理太大了，得先划边界。作者的做法是从大学普通物理教材（Halliday &amp; Resnick &amp; Walker）出发，选出四个「视觉上可见」的领域：力学、光学、流体、磁学；明确排除热学和声学，因为它们要么看不见，要么需要温度、声音这类超出视频范畴的额外感知通道。这个取舍很干净——数据集的模态决定了它能覆盖的物理。</p><p>第二个问题是<strong>真值从哪来</strong>。真实拍摄拿不到 3D 网格、材料参数、精确轨迹这些标注，所以只能走合成。走合成就意味着要接受一层仿真误差，作者的辩护是这些误差已经被充分研究和控制，而且近期工作已经证明合成视频能提升物理保真度。</p><p>第三个问题是<strong>怎么做出复杂度</strong>。如果只是把 71 种现象各渲一遍，你得到的还是一个「单现象、干净背景」的数据集，和前人没有本质差别。真实世界的物理活动往往是多个现象同时或先后发生的。于是有了组合的思路：把基本现象两两、三三组合成复合活动。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0622em;vertical-align:-0.2481em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4519em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">71</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2481em;"><span></span></span></span></span></span></span></span></span></span> 有 2485 种组合，但很多物理上无意义（比如「激光反射」配「气球浮空」没什么可交互的），所以要人工筛选，最终留下 943 个双物理活动和 2270 个三物理活动。</p><p>第四个问题是<strong>怎么让规模上去</strong>。同一个概念性的活动可以实例化成很多具体场景——换物体、换材质、换背景。加上多机位渲染（12 个固定 + 1 个运动），一个场景就变成 13 段视频。3284 个活动 × 平均 46.84 个场景 × 13 个视角，就到了 200 万段。</p><p>第五个问题是<strong>怎么证明它有用</strong>。数据集论文最容易被质疑的就是「所以呢」，所以要挑几个下游任务实测。作者选了四个：物理感知视频生成、长/短期未来帧预测、物理属性估计、运动迁移——分别对应生成、预测、逆问题、编辑四类用途。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>前人做「从视觉学物理」的数据集时，为了拿到干净的真值，把场景简化成了纯色小球撞纯色立方体——结果是数据里的物理干净了，但和真实世界的物理没什么关系。PhysInOne 的赌注是：<strong>现代游戏引擎加上 MPM/SPH，已经足以在复杂物体和复杂背景下同时保住物理正确性和视觉真实性</strong>，所以没必要再牺牲复杂度换真值。一旦这个前提成立，规模就只是工程量问题，而规模正是这个领域一直缺的东西。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>3D 资产收集</strong>。2,231 个日常物体（约 163 类），来自 Sketchfab、FAB、BlenderKit，全部可免费商用。按物理行为分六类：<strong>solid</strong>（锤子、砖块，交互中保持形状）、<strong>interactable</strong>（有可动部件如可旋转风扇，用 UE Blueprints 实现）、<strong>destructible</strong>（可碎玻璃，用 UE Geometry Collections）、<strong>deformable</strong>（形状会变，MPM 仿真）、<strong>granular</strong>（沙子等颗粒，MPM）、<strong>liquid</strong>（水、奶油、牛奶，SPH）。另有 623 种材质，分塑料、金属、木材、石材、织物五类，每种材质的摩擦系数、密度、恢复系数都可调，从而衍生出大量场景变体。528 个 3D 背景，覆盖客厅、卧室、工厂、泳池等不同空间尺度的室内外环境。</p><p><strong>场景构建四步</strong>：(1) 组合出 71 + 943 + 2270 = 3284 个物理活动；(2) 为目标活动配上物理上说得通的背景；(3) 在背景里放置一个或多个资产；(4) 变换材质与物性参数。最终 153,810 个场景，每个活动平均实例化成 46.84 个场景。场景复杂度随活动复杂度上升：单/双/三物理活动的平均资产数分别是 3.9 / 6.3 / 7.8。</p><p><strong>仿真</strong>。UE5 内置的 Chaos Physics 处理大部分日常现象；可形变与颗粒物体用 Taichi 实现的 MPM；液体用 Doriflow 的 SPH。</p><p><strong>渲染</strong>。每个场景 12 台静态相机均匀布在上半球、俯仰角 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6741em;"></span><span class="mord">3</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6741em;"></span><span class="mord">6</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∘</span></span></span></span></span></span></span></span></span></span></span>（具体位置随场景空间布局与背景而变），外加 1 台沿预定义轨迹（通常在随机俯仰角上环绕活动）的运动单目相机。分辨率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1120</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1120</span></span></span></span>，30 FPS（含激光活动的 8780 个场景用 60 FPS），平均 5.2 秒。</p><p><strong>标注</strong>。文本描述人工撰写、用 Qwen3 校对语法，平均每场景约 64 个英文词。渲染时同步产出深度图、逐帧物体掩码、动态物体的 3D 轨迹、物体网格、材质属性。五个方面齐全：几何、语义、运动、物理属性、文本。</p><p><strong>划分</strong>。train/val/held-out test 按 8:1:1，且<strong>保证每个 3D 资产只出现在一个划分里</strong>以防泄漏。</p><p><strong>四个下游应用</strong>：</p><ul><li><strong>物理感知视频生成</strong>：微调 SVD-XT（UNet, I2V）、CogVideoX-1.5-5B（Transformer, TI2V）、Wan2.2-5B（Transformer + flow matching, TI2V），三种微调方式 LoRA / SFT / FLT（Final Layer Tuning），训练用随机采的 83,650 条文本-视频对，评测在 test-small（772 条）。</li><li><strong>未来帧预测</strong>：长期任务预测后半段（约 2.6 秒、约 78 帧），在 test-mini（103 场景）上评 4D 建模方法（TiNeuVox、DefGS、TRACE、FreeGave，可在已见与新视角上预测）与视频预测方法（ExtDM 从零训在同样的 83,650 条上，MAGI-1 用预训练模型）。短期任务模拟机器人操作，要求实时连续预测下 10 帧。</li><li><strong>物理属性估计</strong>：在 test-tiny（20 场景，5 类材料各 4 个）上评 PAC-NeRF 与 GIC，估计杨氏模量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span>、泊松比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span></span></span></span>、屈服应力 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">Y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、剪切模量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>、塑性黏度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span></span></span></span>、体积模量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span>、摩擦角 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 以及初速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">v</span></span></span></span></span></span>，再用估出的参数在新初始条件下重仿真、与真值物理渲染的参考视频对比。</li><li><strong>运动迁移</strong>：在 273 个 val 场景上评 MotionPro 与 GoWithTheFlow。配对目标场景的构造方式是把源场景的物体换成别的形状材质、<strong>保持物理活动完全相同</strong>，这样就有了定量评测的参考。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化主要集中在新提出的评价指标上。</p><p><strong>Physical Motion Fidelity（PMF）</strong>。传统的 FVD 只评视觉真实性，不评运动的物理合理性；用 VLM 打分（如 VideoScore、VideoPhy 的 auto-rater）作者认为不可靠，因为这些模型本身就不理解物理定律；QA 式基准则是定性的，无法定量衡量运动正确性。</p><p>PMF 的构造思路是：给定一段物理正确的参考视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>（来自测试集）和一段用<strong>相同初始帧与相同文本 prompt</strong> 生成的视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，对两者做离散傅里叶变换，比较其能量（幅值平方）：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">PMF</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathrm">DFT</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">DFT</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>PMF 越高表示与参考的运动模式偏离越小。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的具体形式在正文中未给出（论文指向附录，而附录该部分在 HTML 中未渲染），因此<strong>本文不对其具体定义做任何断言</strong>。</p><p>这个指标的 intuition 值得说清楚：视频信号的时域频谱直接编码了运动的节律与速率——一个自由落体的加速过程、一次碰撞后的突变、一段周期性摆动，在频域上各有特征。比较频域能量而不是逐像素差，是因为生成任务里帧级对齐既做不到也不必要（作者原话）。控制变量的关键在于「相同初始帧、相同 prompt」，这样两段视频的差异才主要来自动力学而非内容。</p><p><strong>物理定律</strong>。数据生成侧严格遵循牛顿定律、质量守恒、（角）动量守恒、胡克定律、伯努利原理等；附录列出了 71 种现象各自对应的定律。五类材料的动力学由不同参数组控制：弹性固体由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span></span></span></span>；橡皮泥由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">Y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；牛顿流体由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">κ</span></span></span></span>；非牛顿流体由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">Y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">η</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">κ</span></span></span></span>；颗粒物质由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：在 PhysInOne 上微调能提升物理合理性吗？</strong> 表 2 左半部分。SVD 原始 PMF 2.753 / FVD 203 / 人评 6.09；SVD-SFT 提到 3.147 / 143 / 6.08。Wan2.2-5B 原始 2.041 / 258 / 2.26；Wan-LoRA 2.785 / 178 / 4.80；Wan-SFT 2.978 / 190 / 5.95。作者的结论是 SVD 和 Wan2.2 有显著提升，<strong>尤其是用 SFT</strong>。</p><p>如实指出几处论文措辞之外的事实：SVD 的 LoRA（2.446）和 FLT（2.464）版本的 PMF 都<strong>低于</strong>原始 SVD（2.753），人评也从 6.09 掉到 5.82 和 5.45；也就是说微调方式选错了会变差。CogVideoX 几乎没变（2.877→2.869，LoRA），论文对此未加评论。Wan-FLT 的 FVD 从 258 恶化到 341。</p><p><strong>问题二：PMF 与人类感知一致吗？</strong> 论文声称「人类对物理动态的感知与 PMF 高度相关」。这一点在<strong>模型内部</strong>成立（SVD 系列里 SFT 的 PMF 和人评都最高），但<strong>跨模型</strong>并不成立：CogVideoX 的 PMF 2.877 高于原始 SVD 的 2.753，人评却是 2.98 对 6.09，差了一倍多；Wan-SFT 的 PMF 2.978 高于 SVD-SFT 的 3.147 吗？不，2.978 &lt; 3.147，但人评 5.95 &lt; 6.08，这一对是一致的。真正的矛盾在 CogVideoX 上。这个不一致论文没有讨论，见 §9。</p><p><strong>问题三：不同物理领域难度一样吗？</strong> 表 2 右半部分给出四个领域的 PMF。作者的结论是多数模型在<strong>磁学与流体上更准，在力学与光学上更差</strong>。以 SVD-SFT 为例：力学 3.139、磁学 3.948、光学 3.261、流体 3.868。这个模式有解释力——磁吸/磁斥和流体流动的视觉模式相对刻板，力学涉及大量接触与碰撞的分支情况，光学的反射几何要求精确的角度关系。</p><p><strong>问题四：现有方法能预测未来吗？</strong> 长期预测（约 78 帧）在 test-mini 上，格式为「已见视角 / 新视角」。DefGS 3.980/3.347 PMF、22.85/17.95 PSNR；FreeGave 3.897/3.265、22.57/17.75；TRACE 3.869/3.242；TiNeuVox 3.710/2.885；ExtDM 3.363（仅已见）；MAGI-1 4.086（仅已见，PSNR 23.14 最高）。结论很清楚：<strong>在训练视角上尚可，换新视角就崩</strong>，PSNR 普遍掉 5 dB 左右。短期预测（10 帧）整体好得多：FreeGave 4.742/3.706、PSNR 27.09/20.80；MAGI-1 4.696、LPIPS 0.116 最优；但新视角的差距依然存在。</p><p><strong>问题五：能反推物理参数吗？</strong> PAC-NeRF 与 GIC 在 test-tiny 上的误差（表 5）普遍很大，例如非牛顿流体上 PAC-NeRF 的四个参数误差分别是 309.42、552.89、339.20、65.60，GIC 是 124.26、181.87、28.78、24.97；牛顿流体的黏度误差 PAC-NeRF 287.56、GIC 70.07。重仿真结果（表 6）PAC-NeRF PMF 5.617 / PSNR 24.12 / SSIM 0.942 / LPIPS 0.086，GIC 5.938 / 26.90 / 0.950 / 0.074。作者的结论是两者虽能推出物理上说得通的属性，但在复杂物体与复杂背景下精度不足。</p><p><strong>问题六：能迁移物理运动吗？</strong> GoWithTheFlow 3.309 / 18.98 / 0.691 / 0.410，MotionPro 3.484 / 20.28 / 0.775 / 0.467。两者视觉保真度尚可但<strong>都无法准确迁移复杂物理运动</strong>（图 6 里移动的车、下落的球都失败）。注意 MotionPro 的 PSNR/SSIM/PMF 全面更好但 LPIPS 更差（0.467 vs 0.410），说明两者的失败模式不同。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：PhysInOne 用 UE5 Chaos + Taichi MPM + Doriflow SPH 造出 153,810 个多物体多物理 3D 场景，13 机位渲成 200 万段视频，覆盖力学、光学、流体、磁学四域的 71 种基本现象，规模比既有同类数据集高数个数量级。关键的复杂度来源是组合：71 种基本现象被人工筛选组合成 943 个双物理与 2270 个三物理活动，场景平均含 3.9–7.8 个物体并置于 528 种真实背景中。标注覆盖几何、语义、运动、物理属性、文本五个方面，且划分时保证 3D 资产不跨集泄漏。四个下游任务的实验显示：SFT 微调能显著提升 PMF，但 LoRA 与 FLT 在 SVD 上反而使其下降；未来帧预测在新视角上普遍崩溃；物理属性估计与运动迁移在复杂场景下均不达标。论文同时提出用频域能量比较的 PMF 指标来定量衡量运动的物理保真度。</p><p><strong>3 句话版</strong>：这是目前规模最大的视觉物理数据集——15.4 万场景、200 万视频、71 种现象、多物体复杂背景、五类真值标注齐全。四个应用实验既证明了微调能提升物理合理性，也暴露了现有方法在新视角预测、物性反演和运动迁移上的系统性不足。新提的 PMF 指标用 DFT 能量比较代替像素级相似度。</p><p><strong>1 句话版</strong>：把「从视觉学物理」的训练数据从几千条一次性推到两百万条，顺带证明现有方法的瓶颈不全在数据。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>最脆弱的一条是：在 PhysInOne 的合成渲染上取得的改善，能迁移到真实视频上。</strong></p><p>整套论证的价值主张是「微调后模型的物理合理性显著增强」。但<strong>论文所有的评测都在 PhysInOne 自己的留出集上完成</strong>——test-small（772 条）、test-mini（103 场景）、test-tiny（20 场景）都由同一条 UE5/MPM/SPH 流水线渲出。论文<strong>没有在 VideoPhy、VideoPhy-2、Physics-IQ 或任何真实视频基准上报告微调后模型的表现</strong>（这些基准在相关工作里被大量引用，却没有出现在实验里）。</p><p>问题的严重性还被 PMF 的定义放大了：PMF 是把生成视频与<strong>同一渲染器产出的参考视频</strong>做频域能量比较。也就是说，一个学会了 UE5 特有的运动模糊、帧间时序统计、以及仿真器特有的接触响应节律的模型，会在 PMF 上直接获益，而这与它是否理解物理无关。FVD 的同步大幅改善（SVD 203→143）也正是域适应的典型表现——FVD 本身就是分布距离。</p><p>如果这条假设不成立，核心 claim「fine-tuning foundation models on PhysInOne significantly enhances physical plausibility」就要限缩为「…enhances plausibility <strong>on PhysInOne-style renders</strong>」，数据集的价值也从「训练资源」退回到「诊断基准」。这不是致命打击，但性质完全不同。</p><p>论文为迁移性提供的间接证据只有一句：引用了一项近期工作说明合成视频能提升物理保真度。这不足以支撑自己的结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做，直接检验 §9：</p><ol><li>取一个可在单机微调的开源视频模型（如 CogVideoX-2B 或更小的 I2V 模型）。</li><li>从 PhysInOne 采 5,000–10,000 条文本-视频对（比论文的 83,650 小一个量级，但足够看趋势），用 SFT 微调（论文中唯一稳定有效的方式）。</li><li><strong>在两个测试集上同时评测</strong>：(a) PhysInOne 的 test-small，报告 PMF 与 FVD；(b) <strong>VideoPhy-2 与 Physics-IQ</strong>，用官方 auto-evaluator 报告 PC / Physics-IQ Score。</li><li>加一个关键对照：用<strong>同等数量的通用真实视频</strong>（如 OpenVid 的随机子集）做同样的 SFT，同样在两个测试集上评。</li></ol><p>判据：如果 PhysInOne 微调在 (a) 上大涨而在 (b) 上持平甚至下降，且通用视频对照在 (a) 上也有部分提升，那么 PMF 的改善主要是域适应；如果 (b) 上也有明确提升且显著超过通用视频对照，那么合成到真实的迁移成立，数据集的训练价值被证实。这个实验成本很低，却是整篇论文最需要而恰好缺失的一格。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>除了 §9 的域内评测问题，还有一个更直接的攻击点：<strong>PMF 作为&quot;物理保真度&quot;指标的有效性尚未被论文自己的数据支持</strong>。</p><p>论文声称「人类对物理动态的感知与我们新提的 PMF 高度相关」。但把表 2 的数字排开就会看到反例：<strong>CogVideoX 的 PMF 是 2.877，高于原始 SVD 的 2.753；而它的人评只有 2.98，SVD 是 6.09</strong>。一个 PMF 更高的模型，人类打分只有对方的一半。同样地 Wan-FLT 的 PMF 2.227 高于 SVD-LoRA 的 2.446 吗？不，低于；但 Wan-FLT 人评 2.61、SVD-LoRA 5.82，差距远大于 PMF 差距所暗示的。也就是说，PMF 与人评的相关<strong>只在同一模型家族内部成立，跨家族失效</strong>。这恰恰是一个指标最需要成立而它不成立的地方——因为跨模型比较正是指标的主要用途。</p><p>一个自然的替代解释是：PMF 度量的是频谱能量的接近程度，而不同模型的<strong>基础画质与时序噪声水平</strong>差异很大。一个画面抖动、有闪烁伪影的模型会在高频段积累能量；如果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9805em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">er</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 的定义对此不敏感甚至受益，PMF 就会奖励噪声。</p><p><strong>具体实验</strong>：构造三组对照视频，全部与同一段参考视频比较 PMF：(i) 参考视频本身加高斯像素噪声；(ii) 参考视频做时序抽帧再插值（运动变慢、频谱左移）；(iii) 参考视频完全冻结成静止画（运动能量趋零）。若 (i) 的 PMF 没有明显下降，说明指标对噪声不敏感；若 (iii) 的 PMF 不是垫底，说明指标无法区分&quot;没有运动&quot;和&quot;运动正确&quot;。再补一个跨模型的人类评测：取 100 组同 prompt 的生成结果，做成对比较，计算 PMF 排序与人类偏好排序的 Kendall <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>——论文只报了模型级的定性一致，没有报这个数。</p><p>一个可预测的失败场景：光学类现象。激光反射的正确性取决于<strong>入射角等于反射角</strong>这个精确的几何关系，但反射光斑在画面中占的像素极少，对整段视频的频谱能量贡献接近于零。因此一个把激光反射角完全算错的模型，PMF 可能几乎不受影响。这也解释了为什么表 2 里光学的 PMF 分数普遍偏低却波动很大——该维度上指标本身的分辨力可能就不足。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：PhysInOne 拥有整个领域最丰富的真值——每个物体的网格、3D 轨迹、材质参数、逐帧掩码、深度都在——但四个应用里，这些标注绝大部分<strong>只被用来评测，没有被用来训练</strong>。视频生成的微调只用了「文本-视频对」，等于把一个带完整物理状态的数据集当成了普通的视频语料。这正是为什么模型学到的可能只是渲染器的像素统计（§9）。</p><p><strong>新的 framing</strong>：不要训「文本 → 像素」，训「观测 → 物理状态轨迹 → 渲染」。即让模型输出一条显式的物理状态序列（每个物体的位姿、速度、材质参数），再由一个<strong>可微仿真器 + 可微渲染器</strong>把它变成视频，用视频损失反传。这把泛化的载体从像素统计换成了物理参数——模型在新材质、新初始条件下的泛化，变成了参数外推而非分布外生成。同时它自带可解释性与可干预性：你可以直接读出模型认为的质量和摩擦系数，也可以修改它们再重放。PhysInOne 是<strong>目前唯一有能力监督这条路线的数据集</strong>，因为它同时提供了物理参数真值和多视角视频。</p><p><strong>可借鉴的相邻领域</strong>：可微物理仿真（DiffTaichi、Warp 这类已经把 MPM/刚体求解器做成可微的）；系统辨识与 Neural ODE（如何从观测反推动力学参数，以及可辨识性的条件）；PAC-NeRF/GIC 这条线本身就是雏形，只是它们是<strong>场景特化</strong>的（每个场景重新优化），缺的正是一个能训出<strong>跨场景泛化</strong>的前馈模型的数据规模。</p><p><strong>第一个实验</strong>：在 test-tiny 之外取 PhysInOne 中 2,000 个含单一可形变或流体物体的场景，训一个前馈网络：输入前 0.5 秒的多视角视频，输出该物体的材料参数（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">Y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">κ</span></span></span></span>）与初速度；用真值参数做直接监督（这是 PAC-NeRF/GIC 拿不到的监督信号）。评测分三档：(i) 参数误差，与 PAC-NeRF/GIC 的场景特化优化结果对比；(ii) 用预测参数在真实仿真器里 rollout，与真值轨迹比 PMF 与 PSNR；(iii) <strong>关键的泛化测试</strong>——在训练时未出现的材质组合与初始条件上重复 (i)(ii)。如果前馈模型在 (iii) 上仍能保住精度，就说明「先估物理参数再仿真」这条路线比「直接生成像素」更能泛化，也顺带绕开了 §9 的合成到真实迁移问题——因为物理参数本身是与渲染器无关的量。</p>',72)])])}const d=a(e,[["render",l]]);export{c as __pageData,d as default};
